import{z as A,x as B,o as r,c as u,q as o,j as i,D as t,d as a,s as l,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const q=JSON.parse('{"title":"资源模型与 QoS","description":"","frontmatter":{"title":"资源模型与 QoS","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/orch-resource-qos.md","filePath":"cs/orch-resource-qos.md","lastUpdated":1791413859000}'),p={name:"cs/orch-resource-qos.md"};function d(c,e,m,C,f,h){const s=B("Mermaid");return r(),u("div",null,[e[2]||(e[2]=o('<h1 id="资源模型与-qos" tabindex="-1">资源模型与 QoS <a class="header-anchor" href="#资源模型与-qos" aria-label="Permalink to &quot;资源模型与 QoS&quot;">​</a></h1><div class="epigraph"><p>request 是给调度器看的承诺，limit 是给内核下的死命令；两者的差值就是超售，也是邻居的尾延迟。</p><footer>—— 据 Kubernetes 官方文档（Pod 资源管理）与 Linux cgroup 文档整理</footer></div><p><a href="/cs/orch-rolling-release">上一课</a>把版本切换的容量钉成预算公式；预算的对象——CPU 与内存这本账——本课来管。主干课 <a href="/cs/cgroups">cgroups</a> 给过单机的记账与上限，<a href="/cs/virt-ns-cgroup-deep">namespace 与 cgroup 的深化</a> 把 cgroup 定为「视图加预算」里的预算；本课拆编排层怎么把两个数字（request、limit）编译成内核参数，以及两者怎么组合出三档 QoS。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>只有一个数字（上限）时，设的人两头挨打：设小了高峰被掐，设大了平时浪费、邻居被挤。缺口是把两种语义拆开：<strong>承诺</strong>（我保证要这么多，调度时给我留）与<strong>上限</strong>（我最多用到这么多，运行时给我封顶）。承诺进调度器的账本，决定放哪；上限进内核的账本，决定跑起来怎么管。两个数字再组合出档位：全设满、设一半、全不设——QoS 不是用户声明的第三个字段，是推导出来的结论。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每个容器填 requests 与 limits 两栏。落地是编译：CPU 的 request 变成 cgroup 的权重（idle 时按权重分时间片），CPU 的 limit 变成带宽配额（按周期节流），内存的 limit 变成硬上限（超限触发组内终止）。调度器按 request 过滤节点——上一课的过滤项之一；kubelet 按同样的数字落地——账本在两层必须同源。组合出三档：CPU 与内存都 request 等于 limit 的是 Guaranteed；都不设的是 BestEffort；其余是 Burstable。内存吃紧时按档位调整OOM 评分调整值：BestEffort 最先被选中终结。</p><p><span class="marginnote">术语翻译：request 是「占座」——进场前告诉领班需要几人桌，调度器按它安排位置；limit 是「限购」——开吃后每人最多拿这么多。占座决定你能不能进场，限购决定进场后能拿多少，两件事互不替代：只填限购不占座，领班根本不知道该给你留多大的位置。</span></p>',8)),(r(),i(n,null,{default:t(()=>[l(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SPEC%5B%22requests%20%E4%B8%8E%20limits%22%5D%20--%3E%20SCH%5B%22%E8%B0%83%E5%BA%A6%E5%99%A8%3A%20%E6%8C%89%20request%20%E8%AE%B0%E8%B4%A6%22%5D%0A%20%20SCH%20--%3E%20NODE%5B%22kubelet%20%E7%BC%96%E8%AF%91%E6%88%90%20cgroup%22%5D%0A%20%20NODE%20--%3E%20W%5B%22CPU%20request%3A%20%E6%9D%83%E9%87%8D%E5%88%86%E6%97%B6%22%5D%0A%20%20NODE%20--%3E%20QUOTA%5B%22CPU%20limit%3A%20%E5%91%A8%E6%9C%9F%E8%8A%82%E6%B5%81%22%5D%0A%20%20NODE%20--%3E%20MEM%5B%22%E5%86%85%E5%AD%98%20limit%3A%20%E7%A1%AC%E4%B8%8A%E9%99%90%22%5D%0A%20%20MEM%20--%3E%20OOM%5B%22%E6%8C%89%20QoS%20%E8%AE%BE%20oom%20%E8%AF%84%E5%88%86%22%5D%0A%20%20OOM%20--%3E%20KILL%5B%22%E5%86%85%E5%AD%98%E5%8E%8B%E5%8A%9B%E6%97%B6%E6%8C%89%E5%88%86%E6%8C%91%E7%89%BA%E7%89%B2%E8%80%85%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=E("h2",{id:"机制",tabindex:"-1"},[a("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=E("p",null,[a("全部机制长在"),E("strong",null,"可压缩与不可压缩"),a("的分野上：CPU 超限只是变慢，下个周期重来；内存超限是死亡，见 "),E("a",{href:"/cs/oom-killer"},"OOM killer"),a("。所以 Guaranteed 才能承诺「不受邻居影响」——CPU 拿满自己的配额，内存压力的驱逐名单里排最后。这个承诺有价：request 等于 limit 意味着不参与超售，密度换隔离。反过来，request 与 limit 的差值是集群的超售空间：所有 pod 的 request 之和可以小于物理量，节点因此装得更多——代价是争用时 BestEffort 与 Burstable 的超出部分互相挤，长尾就是这笔账的利息，"),E("a",{href:"/cs/tail-at-scale"},"Tail at Scale"),a(" 的输入之一。")],-1)),(r(),i(n,null,{default:t(()=>[l(s,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20PRESS%5B%22%E8%8A%82%E7%82%B9%E5%86%85%E5%AD%98%E5%90%83%E7%B4%A7%22%5D%20--%3E%20SCORE%5B%22%E9%80%90%E4%B8%AA%E8%AE%A1%E7%AE%97%20oom%20%E8%AF%84%E5%88%86%3A%20%E7%94%A8%E9%87%8F%E5%8A%A0%E8%B0%83%E6%95%B4%E5%80%BC%22%5D%0A%20%20SCORE%20--%3E%20BE%5B%22BestEffort%3A%20%E4%BB%80%E4%B9%88%E9%83%BD%E6%B2%A1%E5%A1%AB%2C%20%E8%AF%84%E5%88%86%E6%9C%80%E9%AB%98%22%5D%0A%20%20BE%20--%3E%20KILL1%5B%22%E6%9C%80%E5%85%88%E8%A2%AB%E9%80%89%E4%B8%AD%E7%BB%88%E7%BB%93%22%5D%0A%20%20SCORE%20--%3E%20BU%5B%22Burstable%3A%20%E9%83%A8%E5%88%86%E5%A1%AB%E5%86%99%2C%20%E8%AF%84%E5%88%86%E5%B1%85%E4%B8%AD%22%5D%0A%20%20BU%20--%3E%20KILL2%5B%22%E6%8C%89%E8%AF%84%E5%88%86%E4%BE%9D%E6%AC%A1%E6%8E%92%E9%98%9F%22%5D%0A%20%20SCORE%20--%3E%20GU%5B%22Guaranteed%3A%20request%3Dlimit%2C%20%E8%B0%83%E6%95%B4%E5%80%BC%E6%9C%80%E4%BD%8E%22%5D%0A%20%20GU%20--%3E%20SAFE%5B%22%E6%8E%92%E6%9C%80%E5%90%8E%2C%20%E6%9C%80%E5%8F%97%E4%BF%9D%E6%8A%A4%22%5D%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=o('<p><span class="marginnote">常见误区：初学者容易以为「内存用到 limit 就会变慢」。实际上 CPU 超限只是变慢（下个周期重来），内存超限是直接被杀（OOM 终止），没有「用省一点」的选项；所以把内存 request 报得远低于真实用量，等于把自己排进驱逐名单的前排。</span></p><p>CPU limit 还有一个反直觉的面相：带宽配额按周期发放，多线程容器可能在周期开头把整段配额瞬间烧完，随后整段被冻结——平均利用率很低，尾延迟却有毛刺。不设 CPU limit、只给 request，是实践中常见的解法：让权重去争用，不让周期去截断；代价是失去「最多用多少」的封顶。</p><p><span class="marginnote">数字：CPU 带宽配额的默认周期是 100 毫秒；limit 为 2 核的多线程进程理论上几毫秒就能烧完一个周期的 200 毫秒配额，随后近一个周期被冻结——「均值漂亮、P99 抖动」的经典成因。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>编排不改变内核的隔离残缺：页缓存归谁的记账、NUMA 与中断的归属，都还是单机问题，共享内核的账见 <a href="/cs/virt-ns-cgroup-deep">namespace 与 cgroup 的深化</a>。节点压力驱逐是最后一道闸：软硬阈值触发时按优先级与 QoS 挑牺牲者，它与内存 limit 的组内终止是两条不同的死法。BestEffort 不是「免费」，是「最先被驱逐」；把 request 骗小换调度成功，换来的是运行时被挤的双输。</p><p><span class="marginnote">数字实例：一台 64 核的节点放 100 个容器，各报 request 0.5 核（合计 50 核，调度放行）、各限 limit 2 核（合计 200 核）。没人超限时相安无事；高峰一起冲顶，200 核的需求挤 64 核的物理量，每个容器平均只拿到 0.64 核——limit 与 request 的差值之和就是这份「利息」的来源。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>request 与 limit 是两个语义：调度按承诺记账，内核按上限执法。</li><li>QoS 三档是组合的推导结论，不是第三个字段；OOM 与驱逐按档排序。</li><li>可压缩与不可压缩的分野决定一切：CPU 变慢，内存死亡。</li><li>超售空间等于差值之和：密度与尾延迟做的是同一笔交换。</li><li>出处：Kubernetes 官方文档（Pod 资源管理）；Linux cgroup 文档；Borg 的优先级与分配语义（Verma et al., EuroSys 2015）。</li></ul>',8))])}const S=A(p,[["render",d]]);export{q as __pageData,S as default};
